require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';sh_require_admin();$rows=$db->query('SELECT a.*,u.name,u.email FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetch_all(MYSQLI_ASSOC);$pageTitle='Audit Logs | StudentHub';$assetPrefix='../';require __DIR__.'/../includes/app-header.php';?><h1>Audit logs</h1><div class="p15-card p15-table-wrap"><table class="p15-table"><thead><tr><th>When</th><th>User</th><th>Action</th><th>Entity</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=sh_e($r['created_at'])?></td><td><?=sh_e($r['name']??'Deleted user')?></td><td><?=sh_e($r['action'])?></td><td><?=sh_e($r['entity'])?> #<?=sh_e($r['entity_id'])?></td><td><?=sh_e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/app-footer.php';?>